import React from "react";
import { useAuth } from "../auth/AuthContext";

export default function TopBar() {
  const { user } = useAuth();

  return (
    <div className="fixed top-0 left-0 w-full h-6 bg-black text-white flex items-center justify-end pr-4 z-50 text-sm">
      Angemeldet als: <span className="ml-2 font-semibold">{user?.username || "Gast"}</span>
    </div>
  );
}
